def getcomps8(grid, bg=6, same_color=True):
 seen=set(); comps=[]
 for r in range(len(grid)):
  for c in range(len(grid[0])):
   col=grid[r][c]
   if col==bg or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));pts=[]
   for x,y in q:
    pts.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      if dx==dy==0:continue
      z=(x+dx,y+dy)
      if 0<=z[0]<len(grid) and 0<=z[1]<len(grid[0]) and z not in seen and grid[z[0]][z[1]]!=bg and (not same_color or grid[z[0]][z[1]]==col):
       seen.add(z);q.append(z)
   comps.append((col,pts))
 return comps
