def canonical_poly(pts, rotations=True, reflect=True):
 coords=list(pts)
 variants=[]
 for refl in ([1,-1] if reflect else [1]):
  for k in range(4 if rotations else 1):
   arr=[]
   for x,y in coords:
    x,y=x*refl,y
    for _ in range(k): x,y=y,-x
    arr.append((x,y))
   mi=min(x for x,y in arr); mj=min(y for x,y in arr)
   variants.append(tuple(sorted((x-mi,y-mj) for x,y in arr)))
 return min(variants)
